const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const { canonical } = require('./collaboration-ref-service');

class ChangeBundleService {
  constructor({ store, projects, policyEvidence, collaborationRefs, dataPath }) { this.store = store; this.projects = projects; this.policyEvidence = policyEvidence; this.collaborationRefs = collaborationRefs; this.root = path.join(path.resolve(dataPath), 'change-bundles'); fs.mkdirSync(this.root, { recursive: true }); }
  _path(id) { if (!/^[0-9a-f-]{36}$/.test(String(id || ''))) throw new Error('Change bundle ID is invalid'); return path.join(this.root, `${id}.kcb`); }
  list(projectId) { this.projects.get(projectId); return this.store.snapshot().changeBundles.filter(item => item.projectId === projectId); }
  async create(projectId, iid, actor) { const project = this.projects.get(projectId); const state = this.store.snapshot(); const request = state.mergeRequests.find(item => item.projectId === projectId && item.iid === iid); if (!request) throw Object.assign(new Error('Merge request not found'), { statusCode: 404 }); const id = crypto.randomUUID(); const temporary = path.join(this.root, `${id}.gitbundle.tmp`); try { await this.projects.repositories.run(['bundle', 'create', temporary, `refs/heads/${request.sourceBranch}`, `^refs/heads/${request.targetBranch}`], { cwd: this.projects.repositories.pathFor(project) }); const binary = fs.readFileSync(temporary); if (binary.length > 64 * 1024 * 1024) throw Object.assign(new Error('Portable change bundle exceeds 64 MiB'), { statusCode: 413 }); const evidence = await this.policyEvidence.create(projectId, { mergeRequestIid: iid }, actor); const payload = { format: 'kitsune-change-bundle', version: 1, id, createdAt: new Date().toISOString(), project: { id: project.id, path: `${project.namespace}/${project.slug}` }, mergeRequest: request, reviewThreads: state.reviewThreads.filter(item => item.projectId === projectId && item.mergeRequestIid === iid), qualityGateStatuses: state.qualityGateStatuses.filter(item => item.projectId === projectId && item.mergeRequestIid === iid), policyEvidence: evidence.envelope, sourceRef: `refs/heads/${request.sourceBranch}`, targetRef: `refs/heads/${request.targetBranch}`, gitBundleSha256: crypto.createHash('sha256').update(binary).digest('hex'), gitBundleBytes: binary.length }; const signed = this.collaborationRefs.signPayload(payload); const document = { ...signed, gitBundle: binary.toString('base64') }; fs.writeFileSync(this._path(id), JSON.stringify(document), { mode: 0o600 }); const item = { id, projectId, mergeRequestIid: iid, sourceSha: evidence.sourceSha, bytes: fs.statSync(this._path(id)).size, fingerprint: signed.fingerprint, createdBy: actor, createdAt: payload.createdAt }; return this.store.update(current => { current.changeBundles.push(item); return item; }, { actor, action: 'change-bundle.create', target: id }); } finally { fs.rmSync(temporary, { force: true }); } }
  read(projectId, id) { this.projects.get(projectId); const item = this.store.snapshot().changeBundles.find(value => value.id === id && value.projectId === projectId); if (!item) throw Object.assign(new Error('Change bundle not found'), { statusCode: 404 }); return { item, content: fs.readFileSync(this._path(id)) }; }
  verify(document) { if (document?.payload?.format !== 'kitsune-change-bundle') throw new Error('Portable change bundle format is invalid'); const binary = Buffer.from(String(document.gitBundle || ''), 'base64'); if (binary.length !== document.payload.gitBundleBytes || crypto.createHash('sha256').update(binary).digest('hex') !== document.payload.gitBundleSha256) throw new Error('Portable change bundle Git payload is invalid'); if (!crypto.verify(null, Buffer.from(canonical(document.payload)), document.publicKey, Buffer.from(document.signature, 'base64url'))) throw new Error('Portable change bundle signature is invalid'); return { verified: true, fingerprint: crypto.createHash('sha256').update(document.publicKey).digest('hex'), binary };
  }
  async import(projectId, document, actor) { const project = this.projects.get(projectId); const verified = this.verify(document); const temporary = path.join(this.root, `${crypto.randomUUID()}.import.tmp`); try { fs.writeFileSync(temporary, verified.binary, { mode: 0o600 }); const suffix = `${document.payload.mergeRequest.iid}-${Date.now()}`; const branch = `kitsune-import/${suffix}`; await this.projects.repositories.run(['fetch', temporary, `${document.payload.sourceRef}:refs/heads/${branch}`], { cwd: this.projects.repositories.pathFor(project) }); const event = { id: crypto.randomUUID(), projectId, sourceProject: document.payload.project.path, sourceFingerprint: verified.fingerprint, importedBranch: branch, importedBy: actor, importedAt: new Date().toISOString() }; return this.store.update(state => { state.changeBundleImports.push(event); return event; }, { actor, action: 'change-bundle.import', target: event.id }); } finally { fs.rmSync(temporary, { force: true }); } }
}

module.exports = { ChangeBundleService };
